fn stream_hist(parts:&[Stream])->BTreeMap<usize,u64>{let mut h=BTreeMap::new();for s in parts{for(&n,&c)in &s.stats.hist{*h.entry(n).or_default()+=c;}}h}
fn audit(s:&Stats){assert_eq!(s.generic,8*s.lanes+s.tails);assert_eq!(s.calls,s.hist.values().sum::<u64>());assert_eq!(s.generic,s.hist.iter().map(|(&n,&c)|n as u64*c).sum::<u64>());assert_eq!(s.zero,*s.hist.get(&0).unwrap_or(&0));}
fn run(codes:&[[i16;18]],reps:&[[i128;2]])->Value{
 let n=codes.len();let part=n.div_ceil(2);let r=reps.len();assert_eq!(r,3281);assert!(reps.iter().flatten().all(|x|x.unsigned_abs()<=128));let mut streams=vec![];let mut top=Stats::default();let mut tree=Stats::default();let mut phi=0u64;let mut windows=vec![];
 for w in 0..18{let before=tree.generic+top.generic;let mut parts=vec![];let mut live_parts=0usize;let mut arrivals=0u64;
  for first in (0..n).step_by(part){let last=(first+part).min(n);arrivals+=codes[first..last].iter().filter(|d|d[w]!=0).count()as u64;let p=if w==17{signed_top(codes[first..last].iter().map(|d|d[w]),3*r,&mut top)}else{let mut win=Window::new(3*r);win.feed(codes[first..last].iter().map(|d|d[w]));let(p,s)=win.finish();audit(&s.stats);let occupied=p.iter().filter(|&&b|b).count()as u64;assert_eq!(s.stats.generic+s.projective_mixed+s.finish_joins,s.arrivals-occupied);assert_eq!(s.normalize,s.projective_first);assert_eq!(s.projective_first+s.projective_mixed,s.queued_to_projective);streams.push(s);p};live_parts+=p.iter().filter(|&&b|b).count();parts.push(p);}
  let mut p=parts.remove(0);for other in parts{tree.merge(&mut p,&other);}let maps=p[r..].iter().filter(|&&b|b).count()as u64;phi+=maps;let mut merged=p[..r].to_vec();tree.merge(&mut merged,&p[r..2*r]);tree.merge(&mut merged,&p[2*r..]);let occupied=merged.iter().filter(|&&b|b).count();let mut axes=vec![];
  for axis in 0..2{let mut counts=vec![0usize;128];for(i,rep)in reps.iter().enumerate(){if merged[i]&&rep[axis]!=0{counts[rep[axis].unsigned_abs()as usize-1]+=1;}}let refs:usize=counts.iter().sum();let sums=tree.grouped(&counts);let nonzero=sums.iter().filter(|&&b|b).count();let before=tree.generic;tree.weighted(&sums);axes.push(json!({"axis":axis,"references":refs,"occupied_weight_buckets":nonzero,"weighted_tree_pairs":tree.generic-before}));}
  tree.projective_add_calls+=1;windows.push(json!({"position":w,"arrivals":arrivals,"occupied_part_planes":live_parts,"occupied_representatives":occupied,"phi_maps":maps,"tree_and_top_pairs":tree.generic+top.generic-before,"axes":axes}));
 }
 audit(&top);audit(&tree);let mut stream=stream_value(&streams);stream["ordinary_pair_count_histogram"]=json!(stream_hist(&streams));let generic=stream["affine_pairs"].as_u64().unwrap()+top.generic+tree.generic;
 json!({"rows":n,"stream":stream,"indexed_top":top.value(),"merges_axes_weighted":tree.value(),"generic_affine_total":generic,"affine_unit_phi_maps":phi,"axis_projective_phi_maps":18,"rho_Horner_steps":17,"rho_tripling_calls_if_naive":68,"rho_tau_map_calls_if_naive":17,"rho_unit_map_calls_if_naive":17,"windows":windows,"equal_x_cancellation_modeled":false})
}
#[derive(Default)]struct Ops{v:u64,f:u64,m:u64,s:u64,fs:u64,i:u64,calls:u64,zero:u64,full:u64,tails:u64}
impl Ops{
 fn stream(&mut self,a:&Value){let calls=a["affine_batches"].as_u64().unwrap();let g=a["full_8lane_groups"].as_u64().unwrap();let t=a["scalar_tail_pairs"].as_u64().unwrap();self.v+=7*g+5*calls;self.f+=5*g;self.m+=8*t+calls;self.s+=2*t;self.fs+=4*t;self.i+=calls;self.calls+=calls;self.full+=g;self.tails+=t;}
 fn tree(&mut self,a:&Value){for(n,c)in a["ordinary_pair_count_histogram"].as_object().unwrap(){let n=n.parse::<u64>().unwrap();let c=c.as_u64().unwrap();let g=n/8;let t=n%8;let prefix=n>=32;self.v+=((if prefix{7}else{8})*g+5)*c;self.f+=5*g*c;self.m+=(7*t+1)*c;self.fs+=5*t*c;self.i+=c;self.calls+=c;self.zero+=u64::from(n==0)*c;self.full+=g*c;self.tails+=t*c;}}
 fn value(&self,maps:u64)->Value{json!({"vector_Fq_multiply":self.v,"vector_fused_two_product":self.f,"scalar_Fq_multiply":self.m,"scalar_Fq_square":self.s,"scalar_fused_two_product":self.fs,"scalar_Fq_inversion":self.i,"affine_phi_Fq_multiply_separate":2*maps,"batch_calls_including_zero":self.calls,"zero_pair_tree_inverse_bridges":self.zero,"full_8lane_groups":self.full,"tail_pairs":self.tails,"vector_raw_IFMA_product_proxy":100*self.v+150*self.f,"excludes_scalar_IFMA_expansion_and_inverse_internals":true})}
}
fn field_counts(stream:&Value,top:&Value,tree:&Value,maps:u64)->Value{let mut o=Ops::default();o.stream(stream);o.tree(top);o.tree(tree);o.value(maps)}
fn resources(n:usize,w:usize,r:usize)->Value{
 let slots=3*r;let affine=128usize;let projective=192usize;let parent=w*2*slots*affine;let digits=n*w*2;let axes=w*(2*128*affine+2*projective);let scalar_metadata=if w==18{19683*2+r*4}else{65536+5462+2*r*4+2*(129+128)*8};let indexed_parent_two_parts=2*(6*(2*slots+1)*8+n.div_ceil(2)*4+(n.div_ceil(2).div_ceil(1024)+2*slots)*(16+affine+4)+2*slots*affine+(2*slots).div_ceil(256)*(projective+affine));
 // Payload term only: worst-case projective population, conversion arrays,
 // prefix records, pair indices and borrowed pending pointers. Vector headers,
 // allocator rounding and tree/group scratch are separately excluded.
 let window_leaf_payload=slots*(4+8)+slots.div_ceil(64)*8+slots*(projective+projective+64+affine)+2*200*16+25*2*320+7*5*64;
 let common=parent+digits+axes+scalar_metadata+indexed_parent_two_parts;
 json!({"G2_affine_bytes":affine,"G2_projective_bytes":projective,"bucket_slots_per_part":slots,"all_pending_part_point_payload":parent,"staged_i16_digits_payload":digits,"all_pending_axis_outputs_payload":axes,"scalar_metadata_payload":scalar_metadata,"two_signed_indexed_top_parent_payload_conservative":indexed_parent_two_parts,"parent_payload_sum_excluding_headers":common,"stream_leaf_payload_conservative_not_complete":window_leaf_payload,"stream_leaf_only_workers_32_sum":common+32*window_leaf_payload,"complete_native_workspace_bound":false,"omitted":["allocator rounding and vector headers","indexed tree leaf and axis grouping scratch maxima","retained runtime library scratch capacity","process key/CS/witness/prover allocations","scheduler retained outputs beyond enumerated fixed parents"],"not_RSS_or_minimum_RAM":true})
}
