 let inputs:Value=serde_json::from_slice(&fs::read(format!("{R}/inputs.json")).unwrap()).unwrap();let old:Value=serde_json::from_slice(&fs::read("/home/ubuntu/src/zopro-perf-work/g2-joint-ring-census176/analysis.json").unwrap()).unwrap();let mut cases=vec![];
